import { randomUUID } from "node:crypto";

import { jobRepository } from "../repositories/jobRepository";
import { queueService } from "../services/queueService";
import type { Job, JobPayload } from "../types/job";

type ApiEvent = {
  body?: string | null;
};

type ApiResponse = {
  statusCode: number;
  headers: Record<string, string>;
  body: string;
};

function json(statusCode: number, body: unknown): ApiResponse {
  return {
    statusCode,
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  };
}

function parsePayload(body?: string | null): JobPayload | null {
  if (!body) {
    return {};
  }

  try {
    const parsed = JSON.parse(body);

    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return null;
    }

    return parsed as JobPayload;
  } catch {
    return null;
  }
}

export async function handler(event: ApiEvent): Promise<ApiResponse> {
  const payload = parsePayload(event.body);

  if (payload === null) {
    return json(400, { message: "Request body must be a JSON object" });
  }

  const now = new Date().toISOString();
  const job: Job = {
    id: randomUUID(),
    status: "pending",
    payload,
    createdAt: now,
    updatedAt: now,
  };

  try {
    await jobRepository.save(job);
    await queueService.sendJob({ jobId: job.id });
  } catch (error) {
    console.error("Failed to create job", error);

    return json(500, { message: "Could not create job" });
  }

  return json(202, job);
}
